# LangChain needs extra installs and an LLM API, which this sandbox does not have.
# These small stand-ins behave the same way: @tool turns a function into a Tool with a
# name, a description (its docstring) and .invoke(), and FakeReActLLM answers in the
# ReAct format (Thought / Action / Action Input ... Final Answer).
class Tool:
    def __init__(self, func):
        self.func = func
        self.name = func.__name__
        self.description = (func.__doc__ or "").strip()

    def invoke(self, tool_input):
        return self.func(tool_input)


def tool(func):
    """Mini version of langchain's @tool decorator."""
    return Tool(func)


